ALTER TABLE "builder_proposals" ADD CONSTRAINT "builder_proposals_lane_valid" CHECK ("builder_proposals"."lane" in ('structure','vocabulary','refused'));--> statement-breakpoint
ALTER TABLE "builder_proposals" ADD CONSTRAINT "builder_proposals_status_valid" CHECK ("builder_proposals"."status" in ('ready','applied','rejected','stale','rolled_back'));--> statement-breakpoint
ALTER TABLE "builder_proposals" ADD CONSTRAINT "builder_proposals_usage_valid" CHECK ("builder_proposals"."input_tokens" >= 0 and "builder_proposals"."output_tokens" >= 0 and "builder_proposals"."total_tokens" >= "builder_proposals"."input_tokens" + "builder_proposals"."output_tokens");--> statement-breakpoint
ALTER TABLE "builder_proposals" ADD CONSTRAINT "builder_proposals_changes_valid" CHECK (jsonb_typeof("builder_proposals"."changes") = 'array' and ("builder_proposals"."lane" = 'structure' or jsonb_array_length("builder_proposals"."changes") = 0));--> statement-breakpoint
ALTER TABLE "builder_proposals" ADD CONSTRAINT "builder_proposals_lifecycle_valid" CHECK (("builder_proposals"."status" <> 'applied' or "builder_proposals"."applied_at" is not null) and ("builder_proposals"."status" <> 'rolled_back' or ("builder_proposals"."applied_at" is not null and "builder_proposals"."rolled_back_at" is not null)));